/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { MessageRepository } from 'app/features/notification/message/repository/message-repository.service';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { Message } from 'app/features/notification/message/model/message.model';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de message: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'message-view-bulk-edit-action', standalone: false, template: '' })
export class MessageViewBulkEditActionComponent extends BaseBulkEditAction<Message> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'notification/message';
  protected readonly repository = inject(MessageRepository);

  protected override keyOf(item: Message): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<Message>[] {
    return [
      { name: 'target', label: this.text('fieldTarget'), type: 'text' },
      { name: 'tenant', label: this.text('fieldTenant'), type: 'relation', optional: true },
      { name: 'urgent', label: this.text('fieldUrgent'), type: 'boolean' },
      { name: 'content', label: this.text('fieldContent'), type: 'text' },
      { name: 'retries', label: this.text('fieldRetries'), type: 'number' },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<Message> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
